## Why This Is Asked
This question tests mastery of persistent data structures, real-world versioning systems, and memory-time trade-offs. It also probes understanding of shared nodes and functional update semantics.

## Key Concepts
- Fully persistent data structures via path-copying
- Implicit treap or segment tree with augmented sums and sizes
- Version management with O(log n) mutations per update
- Correct boundary handling for empty intervals and edge operations

## Code Example
```javascript
class Node {
  constructor(val, prio, left = null, right = null) {
    this.val = val;
    this.prio = prio;
    this.left = left;
    this.right = right;
    this.size = 1;
    this.sum = val;
  }

  update() {
    this.size = 1 + (this.left?.size ?? 0) + (this.right?.size ?? 0);
    this.sum = this.val + (this.left?.sum ?? 0) + (this.right?.sum ?? 0);
  }
}

function split(root, k) {
  if (!root) return [null, null];
  const leftSize = root.left?.size ?? 0;
  if (k <= leftSize) {
    const [l, r] = split(root.left, k);
    root.left = r;
    root.update();
    return [l, root];
  } else {
    const [l, r] = split(root.right, k - leftSize - 1);
    root.right = l;
    root.update();
    return [root, r];
  }
}

function merge(left, right) {
  if (!left || !right) return left ?? right;
  if (left.prio < right.prio) {
    left.right = merge(left.right, right);
    left.update();
    return left;
  } else {
    right.left = merge(left, right.left);
    right.update();
    return right;
  }
}

function rangeSum(root, l, r) {
  const [, mid] = split(root, l);
  const [target, rest] = split(mid, r - l + 1);
  const result = target?.sum ?? 0;
  return merge(merge(null, target), rest);
}

function insertAt(root, index, val) {
  const [left, right] = split(root, index);
  const newNode = new Node(val, Math.random());
  return merge(merge(left, newNode), right);
}

function eraseAt(root, index) {
  const [left, mid] = split(root, index);
  const [, right] = split(mid, 1);
  return merge(left, right);
}
```

## Why This Is Asked
This tests a practical DS for dynamic strings with fast prefix queries and duplicates, common in user-name suggestions.

## Key Concepts
- Trie with per-node counters for duplicates
- endCount vs. subCount to distinguish completions from prefixes
- O(length) per operation for add/remove/prefixCount

## Code Example
```javascript
class TrieNode { constructor() { this.next = new Map(); this.subCount = 0; this.endCount = 0; } }
class Trie { constructor(){ this.root = new TrieNode(); }
  addUser(name){ let node = this.root; for (const ch of name){ if (!node.next.has(ch)) node.next.set(ch, new TrieNode()); node = node.next.get(ch); node.subCount++; } node.endCount++; }
  prefixCount(prefix){ let node = this.root; for (const ch of prefix){ if (!node.next.has(ch)) return 0; node = node.next.get(ch); } return node.subCount; }
  removeUser(name){ let stack = [this.root]; let node = this.root; for (const ch of name){ if (!node.next.has(ch)) return; stack.push(node.next.get(ch)); node = node.next.get(ch); }
    if (node.endCount > 0){ node.endCount--; for (let i = name.length - 1; i >= 0; i--){ const c = name[i]; const parent = stack[i]; const child = parent.next.get(c); child.subCount--; if (child.subCount === 0) parent.next.delete(c); } }
  }
``` 

